//go:build amd64

package floats

import "unsafe"

// The AVX2+FMA kernel of PSMixPlan32.Run (psmix32.go), generated by go-asmgen
// (psmix32_amd64_gen.go) into psmix32_amd64.s: every run of a slot in one call, eight rows per
// vector, the short runs and the tails by a full vector that may touch up to 7 rows past a run
// (the contract of psmix32.go; Run proved the lengths). For a CPU with the AVX2+FMA of the other
// kernels (hasAVX2FMA, kernels_amd64.go); the portable loop otherwise. Every operand is passed
// as a pointer to its first element; a source that no run uses is passed as the first plane that
// does (never read). No kernel keeps a pointer: go:noescape.
//
//go:noescape
func psMix32AVX2(nruns int, runs *psMixRun32, gains, tg, sre, sim, lre, lim, rre, rim, d0re, d0im, d1re, d1im, d2re, d2im *float32)

func psMix32(p *PSMixPlan32, gains, tg []float32, s Split32, d *[3]Split32, l, r Split32) {
	if !hasAVX2FMA {
		psMix32Ref(p, gains, tg, s, d, l, r)
		return
	}
	// a source no run uses may be empty: point it at a plane that is held, the kernel does not read it
	var dp [3]Split32
	for q := range dp {
		dp[q] = d[q]
		if p.srcEnd[q] == 0 {
			dp[q] = s
		}
	}
	psMix32AVX2(len(p.runs), unsafe.SliceData(p.runs), &gains[0], &tg[0],
		&s.Re[0], &s.Im[0], &l.Re[0], &l.Im[0], &r.Re[0], &r.Im[0],
		&dp[0].Re[0], &dp[0].Im[0], &dp[1].Re[0], &dp[1].Im[0], &dp[2].Re[0], &dp[2].Im[0])
}
